<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mprocessflowmodel extends CI_Model {    function fnGetProcessFlowInfo($VarProcessFlow = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,processflowname,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_PROCESS_FLOW);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarProcessFlow <> '') {            $ArrWhere['processflowname'] = trim($VarProcessFlow);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckProcessFlow($VarProcessFlow = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,processflowname,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_PROCESS_FLOW);       // $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarProcessFlow <> '') {            $ArrWhere['processflowname'] = trim($VarProcessFlow);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        return $this->db->where($ArrWhere)->count_all_results();    }    function saveProcessFlowInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetProcessFlowInfo($ArrUpdateData['processflowname'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_PROCESS_FLOW, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This garment process flow already exists";            }        } else {            $ArrCheckExist = $this->fnCheckProcessFlow($ArrUpdateData['processflowname'], $VarId, $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_PROCESS_FLOW, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This garment process flow already exists";            }        }        return $ArrResult;    }    function fnCountProcessFlow($VarProcessFlow = '', $VarStatus = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarProcessFlow <> '') {            $ArrWhere[] = "pn.processflowname like '%" . $VarProcessFlow . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }        $VarSqlProcessFlow = "SELECT count(1) as trec  FROM " . KN_MASTER_PROCESS_FLOW . " AS pn LEFT JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlProcessFlow)->row();        return $ObjRows->trec;    }    function fnListProcessFlow($VarProcessFlow = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array("1" => 'pn.processflowname', '2' => 'pn.status', '3' => 'u.contactname', '4' => 'pn.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'pn.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarProcessFlow <> '') {            $ArrWhere[] = "pn.processflowname like '%" . $VarProcessFlow . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }        // removed this line  . " limit " . $VarLimitInfo in below query        $VarSqlProcessFlow = "SELECT pn.id,pn.processflowname,u.contactname,pn.datecreated,pn.dateupdated,pn.status FROM " . KN_MASTER_PROCESS_FLOW . " AS pn LEFT JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlProcessFlow);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_PROCESS_FLOW, array('status' => $optvalue))) {            return true;        }        return false;    }}